css:
  * { box-sizing: border-box; }
  html, body { margin: 0; padding: 0; }
  @page {
    size: Letter;
    margin: 0.55in 0.6in 0.55in 0.6in;
  }
  body {
    font-family: 'Carlito', 'Calibri', 'Liberation Sans', Arial, sans-serif;
    font-size: 11pt;
    line-height: 1.55;
    color: #1f2937;
  }

  /* --- LOGO BAND --- */
  .logo-band {
    background: white;
    text-align: center;
    padding: 0 0 10px 0;
  }
  .logo-band img {
    width: 100%;
    max-width: 100%;
    height: auto;
    max-height: 60px;
    display: block;
    object-fit: contain;
    margin: 0 auto;
  }

  /* --- HERO --- */
  .hero {
    background: #003a70;
    color: white;
    padding: 18px 24px;
    border-radius: 8px;
    margin-bottom: 16px;
  }
  .hero h1 {
    font-size: 22pt;
    margin: 0 0 6px 0;
    font-weight: 700;
    letter-spacing: -0.5px;
    color: white;
    display: inline;
  }
  .hero .edition-inline {
    color: white;
    text-transform: uppercase;
    letter-spacing: 2.5px;
    font-size: 9pt;
    font-weight: 700;
    margin-left: 10px;
    vertical-align: middle;
    white-space: nowrap;
  }
  .hero .meta-line {
    margin: 10px 0 0 0;
    font-size: 10pt;
    color: #b9d6ee;
    border-top: 1px solid rgba(98, 181, 229, 0.3);
    padding-top: 8px;
  }
  .hero .meta-line strong { color: white; font-weight: 700; }

  /* --- TYPOGRAPHY --- */
  h2 {
    font-size: 13pt;
    color: #003a70;
    border-bottom: 2px solid #62b5e5;
    padding-bottom: 3px;
    margin: 16px 0 8px 0;
    font-weight: 700;
  }

  /* --- SIGNER INFO GRID --- */
  .signer-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 10px;
    margin-bottom: 4px;
  }
  .signer-card {
    background: #f8fafb;
    border: 1px solid #d8e3eb;
    border-radius: 6px;
    padding: 9px 14px;
  }
  .signer-card .label {
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-size: 8pt;
    font-weight: 700;
    color: #768692;
    margin-bottom: 1px;
  }
  .signer-card .value {
    font-size: 11pt;
    color: #003a70;
    font-weight: 700;
    word-break: break-word;
  }

  /* --- DOCUMENT LIST --- */
  .doc-list { margin: 4px 0 6px 0; }
  .doc-item {
    background: white;
    border: 1px solid #A7F3D0;
    border-left: 4px solid #047857;
    border-radius: 0 6px 6px 0;
    padding: 7px 12px;
    margin-bottom: 5px;
    page-break-inside: avoid;
  }
  .doc-item .doc-row {
    display: flex;
    align-items: center;
    gap: 10px;
  }
  .doc-item .check {
    width: 18px;
    height: 18px;
    border-radius: 50%;
    background: #047857;
    color: white;
    text-align: center;
    line-height: 18px;
    font-size: 10pt;
    font-weight: 700;
    flex-shrink: 0;
  }
  .doc-item .doc-name {
    font-weight: 700;
    color: #111827;
    font-size: 10.5pt;
    flex: 1;
  }
  .doc-item .doc-time {
    font-size: 8.5pt;
    color: #768692;
    text-transform: uppercase;
    letter-spacing: 0.4px;
    font-weight: 600;
    flex-shrink: 0;
    white-space: nowrap;
  }

  /* --- SIGNATURE BLOCK --- */
  .signature-block {
    background: #f8fafb;
    border: 1px solid #d8e3eb;
    border-radius: 8px;
    padding: 12px 16px;
    margin: 4px 0 10px 0;
    page-break-inside: avoid;
  }
  .signature-block .sig-label {
    text-transform: uppercase;
    letter-spacing: 1.5px;
    font-size: 8.5pt;
    color: #768692;
    font-weight: 700;
    margin-bottom: 6px;
  }
  .signature-area {
    background: white;
    border: 1px dashed #d8e3eb;
    border-radius: 6px;
    padding: 10px;
    text-align: center;
    min-height: 60px;
    display: flex;
    align-items: center;
    justify-content: center;
  }
  .signature-area img {
    max-height: 70px;
    max-width: 100%;
    height: auto;
  }
  .signature-meta {
    margin-top: 8px;
    font-size: 9pt;
    color: #495057;
  }
  .signature-meta strong { color: #003a70; }
  .signature-meta .agreement-line {
    border-top: 1px solid #e7e5e4;
    margin-top: 6px;
    padding-top: 6px;
    color: #768692;
    font-size: 8.5pt;
    line-height: 1.5;
    font-style: italic;
  }

  /* --- LEGAL FOOTER --- */
  .legal-footer {
    margin-top: 12px;
    background: #003a70;
    color: white;
    padding: 10px 14px;
    border-radius: 8px;
    font-size: 8.5pt;
    line-height: 1.5;
    text-align: center;
  }
  .legal-footer p { margin: 2px 0; }
  .legal-footer .legal-title {
    text-transform: uppercase;
    letter-spacing: 1.5px;
    font-size: 8pt;
    color: white;
    margin-bottom: 4px;
    font-weight: 700;
  }

